package main

import (
 "database/sql"
 "encoding/json"
 "fmt"
 "net/http"
 "strconv"
 "strings"
)

func sqlIdent(s string) string { return `"`+strings.ReplaceAll(s,`"`,`""`)+`"` }
func adminSchemaTable(r *http.Request) (string,bool) { t:=strings.TrimSpace(r.URL.Query().Get("table")); if t=="" || !validSchemaName(t){return "",false}; var ok bool; if userDB==nil{return "",false}; if e:=userDB.QueryRow(`SELECT EXISTS(SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name=$1 AND table_type='BASE TABLE')`,t).Scan(&ok);e!=nil||!ok{return "",false};return t,true }
func validSchemaName(s string) bool { if len(s)==0||len(s)>63{return false};for _,r:=range s{if !(r=='_'||(r>='a'&&r<='z')||(r>='A'&&r<='Z')||(r>='0'&&r<='9')){return false}};return true }
func schemaColumns(table string)([]string,error){rows,e:=userDB.Query(`SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name=$1 ORDER BY ordinal_position`,table);if e!=nil{return nil,e};defer rows.Close();var out []string;for rows.Next(){var c string;if e:=rows.Scan(&c);e!=nil{return nil,e};out=append(out,c)};return out,rows.Err()}
func schemaColumnMap(table string)(map[string]bool,error){cs,e:=schemaColumns(table);if e!=nil{return nil,e};m:=map[string]bool{};for _,c:=range cs{m[c]=true};return m,nil}
func adminSchemaDataHandler(w http.ResponseWriter,r *http.Request){if !requireAdmin(w,r){return};w.Header().Set("Content-Type","application/json");table:=strings.TrimSpace(r.URL.Query().Get("table"));if table==""{rows,e:=userDB.Query(`SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' ORDER BY table_name`);if e!=nil{http.Error(w,e.Error(),500);return};defer rows.Close();tables:=[]string{};for rows.Next(){var t string;if rows.Scan(&t)==nil{tables=append(tables,t)}};_=json.NewEncoder(w).Encode(map[string]any{"status":"success","schema":"public","tables":tables});return};if !validSchemaName(table){http.Error(w,"Invalid table",400);return};var exists bool;if e:=userDB.QueryRow(`SELECT EXISTS(SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name=$1 AND table_type='BASE TABLE')`,table).Scan(&exists);e!=nil||!exists{http.Error(w,"Table not found",404);return};cr,e:=userDB.Query(`SELECT column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public' AND table_name=$1 ORDER BY ordinal_position`,table);if e!=nil{http.Error(w,e.Error(),500);return};defer cr.Close();type Col struct{Name string `json:"name"`;Type string `json:"type"`;Nullable string `json:"nullable"`};cols:=[]Col{};for cr.Next(){var c Col;if cr.Scan(&c.Name,&c.Type,&c.Nullable)==nil{cols=append(cols,c)}};limit:=200;if n,e:=strconv.Atoi(r.URL.Query().Get("limit"));e==nil&&n>0&&n<=500{limit=n};q:=fmt.Sprintf("SELECT * FROM %s LIMIT %d",sqlIdent(table),limit);rr,e:=userDB.Query(q);if e!=nil{http.Error(w,e.Error(),500);return};defer rr.Close();names,_:=rr.Columns();data:=[]map[string]any{};for rr.Next(){vals:=make([]any,len(names));ptrs:=make([]any,len(names));for i:=range vals{ptrs[i]=&vals[i]};if rr.Scan(ptrs...)!=nil{continue};row:=map[string]any{};for i,n:=range names{v:=vals[i];if b,ok:=v.([]byte);ok{if len(b)>4096{v=string(b[:4096])+" … [truncated]"}else{v=string(b)}};row[n]=v};data=append(data,row)};_=json.NewEncoder(w).Encode(map[string]any{"status":"success","schema":"public","table":table,"columns":cols,"rows":data,"row_limit":limit})}
func adminSchemaWriteHandler(w http.ResponseWriter,r *http.Request){if !requireAdmin(w,r){return};w.Header().Set("Content-Type","application/json");if r.Method!=http.MethodPost{w.WriteHeader(405);return};table,ok:=adminSchemaTable(r);if !ok{http.Error(w,"Table not found",404);return};var in struct{Values map[string]any `json:"values"`;Where map[string]any `json:"where"`};if e:=json.NewDecoder(r.Body).Decode(&in);e!=nil||len(in.Values)==0{http.Error(w,"values are required",400);return};cm,e:=schemaColumnMap(table);if e!=nil{http.Error(w,e.Error(),500);return};keys:=[]string{};args:=[]any{};ph:=[]string{};for k,v:=range in.Values{if !cm[k]{http.Error(w,"Invalid column: "+k,400);return};keys=append(keys,k);args=append(args,v);ph=append(ph,fmt.Sprintf("$%d",len(args)))};var q string;if len(in.Where)==0{q=fmt.Sprintf("INSERT INTO %s (%s) VALUES (%s) RETURNING *",sqlIdent(table),joinIdents(keys),strings.Join(ph,","))}else{wk,wp,wa,e:=buildWhere(in.Where,cm,len(args));if e!=nil{http.Error(w,e.Error(),400);return};args=append(args,wa...);q=fmt.Sprintf("UPDATE %s SET %s WHERE %s RETURNING *",sqlIdent(table),setPairs(keys,1),wp);_ = wk};for i:=range keys{_ = i};if len(in.Where)>0{q=fmt.Sprintf("UPDATE %s SET %s WHERE %s RETURNING *",sqlIdent(table),setPairs(keys,1),buildWhereSQL(in.Where,cm,len(keys)+1));args=append([]any{},args[:len(keys)]...);for _,v:=range in.Where{args=append(args,v)}};var row map[string]any;rows,e:=userDB.Query(q,args...);if e!=nil{http.Error(w,e.Error(),500);return};defer rows.Close();if rows.Next(){names,_:=rows.Columns();vals:=make([]any,len(names));ptrs:=make([]any,len(names));for i:=range vals{ptrs[i]=&vals[i]};if rows.Scan(ptrs...)==nil{row=map[string]any{};for i,n:=range names{row[n]=vals[i]}}};if row==nil{http.Error(w,"No row returned",404);return};_=json.NewEncoder(w).Encode(map[string]any{"status":"success","row":row})}
func joinIdents(a []string)string{out:=make([]string,len(a));for i,v:=range a{out[i]=sqlIdent(v)};return strings.Join(out,",")}
func setPairs(a []string,start int)string{out:=make([]string,len(a));for i,v:=range a{out[i]=fmt.Sprintf("%s=$%d",sqlIdent(v),start+i)};return strings.Join(out,",")}
func buildWhereSQL(m map[string]any,cm map[string]bool,start int)string{keys:=make([]string,0,len(m));for k:=range m{keys=append(keys,k)};sortStrings(keys);out:=make([]string,len(keys));for i,k:=range keys{out[i]=fmt.Sprintf("%s=$%d",sqlIdent(k),start+i)};return strings.Join(out," AND ")}
func buildWhere(m map[string]any,cm map[string]bool,start int)([]string,string,[]any,error){keys:=make([]string,0,len(m));for k:=range m{if !cm[k]{return nil,"",nil,fmt.Errorf("invalid where column: %s",k)};keys=append(keys,k)};sortStrings(keys);args:=make([]any,0,len(keys));for _,k:=range keys{args=append(args,m[k])};return keys,buildWhereSQL(m,cm,start),args,nil}
func sortStrings(a []string){for i:=1;i<len(a);i++{for j:=i;j>0&&a[j]<a[j-1];j--{a[j],a[j-1]=a[j-1],a[j]}}}
func adminSchemaDeleteHandler(w http.ResponseWriter,r *http.Request){if !requireAdmin(w,r){return};w.Header().Set("Content-Type","application/json");if r.Method!=http.MethodPost{w.WriteHeader(405);return};table,ok:=adminSchemaTable(r);if !ok{http.Error(w,"Table not found",404);return};var in struct{Where map[string]any `json:"where"`};if e:=json.NewDecoder(r.Body).Decode(&in);e!=nil||len(in.Where)==0{http.Error(w,"where is required",400);return};cm,e:=schemaColumnMap(table);if e!=nil{http.Error(w,e.Error(),500);return};keys:=make([]string,0,len(in.Where));for k:=range in.Where{if !cm[k]{http.Error(w,"Invalid column: "+k,400);return};keys=append(keys,k)};sortStrings(keys);args:=make([]any,len(keys));for i,k:=range keys{args[i]=in.Where[k]};q:=fmt.Sprintf("DELETE FROM %s WHERE %s RETURNING *",sqlIdent(table),buildWhereSQL(in.Where,cm,1));rows,e:=userDB.Query(q,args...);if e!=nil{http.Error(w,e.Error(),500);return};defer rows.Close();if !rows.Next(){http.Error(w,"No matching row",404);return};_=json.NewEncoder(w).Encode(map[string]any{"status":"success","deleted":true})}
func adminSchemaPageHandler(w http.ResponseWriter,r *http.Request){if r.Method!=http.MethodGet{w.WriteHeader(405);return};w.Header().Set("Content-Type","text/html; charset=utf-8");w.Header().Set("Cache-Control","no-store");_,_=w.Write([]byte(`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>88Task • Public Schema</title><style>body{font:14px system-ui;margin:0;color:#111}.wrap{max-width:1500px;margin:auto;padding:20px}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.controls>*{padding:9px;border:1px solid #ddd;border-radius:8px;background:#fff}.btn{font-weight:700;cursor:pointer}.card{border:1px solid #ddd;border-radius:12px;padding:14px;margin-top:14px;overflow:auto}.muted{color:#777}.cols{display:flex;gap:8px;flex-wrap:wrap}.pill{border:1px solid #ddd;border-radius:8px;padding:6px 9px;font-size:12px}.tablewrap{overflow:auto}table{border-collapse:collapse;min-width:100%;white-space:nowrap}th,td{padding:8px;border-bottom:1px solid #eee;text-align:left;max-width:360px;overflow:hidden;text-overflow:ellipsis}th{font-size:12px;color:#666;position:sticky;top:0;background:#fff}.act{display:flex;gap:5px}.danger{background:#b00020!important;color:#fff}.editor{display:grid;grid-template-columns:repeat(2,minmax(180px,1fr));gap:8px}.editor input{padding:8px;border:1px solid #ddd;border-radius:7px}@media(max-width:700px){.editor{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="controls"><a class="btn" href="/admin">Dashboard</a><select id="tables"><option>Loading…</option></select><input id="limit" type="number" min="1" max="500" value="200"><button class="btn" onclick="loadTable()">Refresh</button><button class="btn" onclick="insertRow()">+ Insert</button></div><div id="info" class="card">Select a table.</div><div id="editor" class="card editor"></div><div id="data" class="card tablewrap"></div></main><script src="/admin-ui.js"></script><script>const key='admin_token',api='/admin/schema/data';function esc(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}async function req(url,opt={}){opt.headers=Object.assign({'Content-Type':'application/json','X-Admin-Token':sessionStorage.getItem(key)},opt.headers||{});let r=await fetch(url,opt);let text=await r.text();let d;try{d=JSON.parse(text)}catch(_){d={message:text}}if(r.status===401){location.href='/admin';return null}if(!r.ok)throw new Error(d.message||'Request failed');return d}async function init(){let d=await req(api);if(!d)return;let s=document.getElementById('tables');s.innerHTML=(d.tables||[]).map(t=>'<option>'+esc(t)+'</option>').join('');if(d.tables?.length)loadTable()}async function loadTable(){try{let t=document.getElementById('tables').value;if(!t)return;let l=document.getElementById('limit').value||200;let d=await req(api+'?table='+encodeURIComponent(t)+'&limit='+encodeURIComponent(l));let cols=d.columns||[],rows=d.rows||[];document.getElementById('info').innerHTML='<b>public.'+esc(d.table)+'</b><div class="cols">'+cols.map(c=>'<span class="pill">'+esc(c.name)+' · '+esc(c.type)+' · '+esc(c.nullable)+'</span>').join('')+'</div><div class="muted">Showing up to '+d.row_limit+' rows. Click Edit to modify a row.</div>';document.getElementById('editor').innerHTML='';document.getElementById('data').innerHTML='<table><thead><tr>'+cols.map(c=>'<th>'+esc(c.name)+'</th>').join('')+'<th>Actions</th></tr></thead><tbody>'+rows.map((r,i)=>'<tr>'+cols.map(c=>'<td title="'+esc(r[c.name])+'">'+esc(r[c.name])+'</td>').join('')+'<td class="act"><button class="btn" onclick=editRow('+i+')>Edit</button><button class="btn danger" onclick=deleteRow('+i+')>Delete</button></td></tr>').join('')+'</tbody></table>';window._rows=rows;window._cols=cols}catch(e){alert(e.message)}}async function editRow(i){let r=window._rows[i],cols=window._cols;let where={};let first=cols.find(c=>r[c.name]!==null&&r[c.name]!==undefined);if(!first){alert('This row has no non-null value to identify it.');return}where[first.name]=r[first.name];document.getElementById('editor').innerHTML='<b>Edit row (matched by '+esc(first.name)+')</b>'+cols.map(c=>'<label>'+esc(c.name)+'<input id="e_'+esc(c.name)+'" value="'+esc(r[c.name])+'"></label>').join('')+'<div><button class="btn" onclick=saveRow('+JSON.stringify(where).replaceAll('"','&quot;')+')>Save</button> <button class="btn" onclick="document.getElementById(\'editor\').innerHTML=\'\'">Cancel</button></div>'}async function saveRow(where){let values={};for(let c of window._cols){let v=document.getElementById('e_'+c.name).value;values[c.name]=v}try{await req('/admin/schema/write?table='+encodeURIComponent(document.getElementById('tables').value),{method:'POST',body:JSON.stringify({where,values})});await loadTable()}catch(e){alert(e.message)}}async function insertRow(){let vals={};for(let c of window._cols){let v=prompt('Value for '+c.name+' (Cancel = omit)');if(v!==null)vals[c.name]=v}if(!Object.keys(vals).length)return;try{await req('/admin/schema/write?table='+encodeURIComponent(document.getElementById('tables').value),{method:'POST',body:JSON.stringify({values:vals})});await loadTable()}catch(e){alert(e.message)}}async function deleteRow(i){let r=window._rows[i],cols=window._cols,first=cols.find(c=>r[c.name]!==null&&r[c.name]!==undefined);if(!first){alert('Cannot identify this row.');return}if(!confirm('Delete this row where '+first.name+' = '+r[first.name]+'?'))return;try{await req('/admin/schema/delete?table='+encodeURIComponent(document.getElementById('tables').value),{method:'POST',body:JSON.stringify({where:{[first.name]:r[first.name]}})});await loadTable()}catch(e){alert(e.message)}}init()</script></body></html>`))}
func init(){http.HandleFunc("/admin/schema",adminSchemaPageHandler);http.HandleFunc("/admin/schema/data",adminSchemaDataHandler);http.HandleFunc("/admin/schema/write",adminSchemaWriteHandler);http.HandleFunc("/admin/schema/delete",adminSchemaDeleteHandler)}

var _ sql.NullString
